with flagged as (select *, case when event_time - lag(event_time) over (partition by page order by event_time, id) > interval 7 days then 1 else 0 end as new_group_flag from web_events), sessionized as (select *, sum(new_group_flag) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_id_2 from flagged) select s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, s.new_group_flag, s.session_id_2, (select avg(w2.duration_sec) from web_events w2 where w2.session_id = s.session_id) as avg_web_event_duration_sec from sessionized s order by duration_sec desc, session_id;
